CREATE TABLE IF NOT EXISTS public.inventory_purchase_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), brand_id uuid NOT NULL REFERENCES public.brands(id), inventory_item_id uuid NOT NULL REFERENCES public.inventory_items(id) ON DELETE CASCADE, purchase_date date NOT NULL DEFAULT CURRENT_DATE, qty numeric NOT NULL CHECK (qty > 0), unit text, notes text, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS inventory_purchase_log_brand_date_idx ON public.inventory_purchase_log(brand_id,purchase_date); ALTER TABLE public.inventory_purchase_log ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS inventory_purchase_log_read_same_brand ON public.inventory_purchase_log; DROP POLICY IF EXISTS inventory_purchase_log_write_same_brand ON public.inventory_purchase_log; CREATE POLICY inventory_purchase_log_read_same_brand ON public.inventory_purchase_log FOR SELECT TO authenticated USING (same_brand(brand_id)); CREATE POLICY inventory_purchase_log_write_same_brand ON public.inventory_purchase_log FOR INSERT TO authenticated WITH CHECK (same_brand(brand_id));